package com.littlemakers.village.rendercheck;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.view.*;import android.view.accessibility.*;import android.widget.*;import java.io.*;import java.lang.reflect.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
/** Isolated emulator checks: wallet-backed wardrobe, illustrated album and one-renderer aquarium HUD. */
public final class Hud34Check extends Instrumentation {
 Activity a;File out;int captures;
 Object field(Object o,String n)throws Exception{Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(o);}
 Object call(Object o,String n,Class<?>[]types,Object...args)throws Exception{Method m=o.getClass().getDeclaredMethod(n,types);m.setAccessible(true);return m.invoke(o,args);}
 void ui(Runnable r){runOnMainSync(r);waitForIdleSync();}
 interface Condition{boolean ok()throws Exception;}
 void waitFor(Condition c,String label)throws Exception{long end=SystemClock.uptimeMillis()+30000;while(SystemClock.uptimeMillis()<end){if(c.ok())return;SystemClock.sleep(80);}throw new AssertionError(label);}
 View desc(View v,String label){if(v.getContentDescription()!=null&&label.contentEquals(v.getContentDescription()))return v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){View found=desc(((ViewGroup)v).getChildAt(i),label);if(found!=null)return found;}return null;}
 void click(String label){ui(()->{View v=desc(a.getWindow().getDecorView(),label);if(v==null)throw new AssertionError("No card: "+label);v.performClick();});}
 int surfaces(View v){int total=v instanceof android.opengl.GLSurfaceView?1:0;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)total+=surfaces(((ViewGroup)v).getChildAt(i));return total;}
 void show(String route){ui(()->{try{call(a,"show",new Class[]{String.class},route);}catch(Exception e){throw new RuntimeException(e);}});}
 void shot(String name)throws Exception{SystemClock.sleep(300);Bitmap b=getUiAutomation().takeScreenshot();if(b==null)throw new AssertionError("capture");try(FileOutputStream f=new FileOutputStream(new File(out,name+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,f);}b.recycle();captures++;Bundle status=new Bundle();status.putString("case",name);sendStatus(1,status);}
 void select(int slot){ui(()->{try{View aquarium=(View)field(a,"aquarium");AccessibilityNodeProvider nodes=aquarium.getAccessibilityNodeProvider();if(nodes==null||nodes.createAccessibilityNodeInfo(slot)==null||!nodes.performAction(slot,AccessibilityNodeInfo.ACTION_CLICK,null))throw new AssertionError("Accessible spot "+slot);}catch(Exception e){throw new RuntimeException(e);}});}
 @Override public void onCreate(Bundle b){super.onCreate(b);start();}
 @Override public void onStart(){Bundle result=new Bundle();try{
  out=new File(getTargetContext().getFilesDir(),"hud34-check");out.mkdirs();getTargetContext().getSharedPreferences("family",0).edit().putString("theme","light").putBoolean("reduce_motion",false).commit();getTargetContext().getSharedPreferences("adventure",0).edit().clear().commit();
  a=startActivitySync(new Intent().setClassName("com.littlemakers.village","com.littlemakers.village.nativeapp.MainActivity").putExtra("destination","friend").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));waitForIdleSync();call(field(a,"db"),"resetLocalProgress",new Class[0]);Object wallet=field(a,"wallet");for(int i=0;i<4;i++)call(wallet,"creativeCompletion",new Class[]{String.class},"story-"+i);ui(()->{try{call(a,"refreshWardrobe",new Class[0]);}catch(Exception e){throw new RuntimeException(e);}});
  waitFor(()->field(a,"previewStage")!=null&&(Long)field(field(a,"previewStage"),"renderedFrames")>1,"wardrobe renderer");if(surfaces(a.getWindow().getDecorView())!=1)throw new AssertionError("wardrobe duplicates GL contexts");Object renderer=field(a,"previewStage");shot("wardrobe");click("Peach friend, 20 coins");if(!(Boolean)call(wallet,"owns",new Class[]{String.class},"peach")||!"peach".equals(call(wallet,"equipped",new Class[]{String.class},"skin")))throw new AssertionError("wallet purchase");if(field(a,"previewStage")!=renderer)throw new AssertionError("purchase recreated the renderer");int coins=(Integer)call(wallet,"coins",new Class[0]);click("Peach friend, Wearing now");if((Integer)call(wallet,"coins",new Class[0])!=coins)throw new AssertionError("equip charged twice");shot("wardrobe-equipped");
  a=startActivitySync(new Intent().setClassName("com.littlemakers.village","com.littlemakers.village.nativeapp.AdventureActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));waitForIdleSync();show("album");if(surfaces(a.getWindow().getDecorView())!=0)throw new AssertionError("album needs no GL");if(desc(a.getWindow().getDecorView(),"A bridge for Turtle, 0 of 3 seeds found")==null)throw new AssertionError("illustrated milestones");shot("album");show("habitat");
  waitFor(()->field(a,"aquarium")!=null&&(Long)field(field(a,"aquarium"),"renderedFrames")>2,"aquarium renderer");if(surfaces(a.getWindow().getDecorView())!=1)throw new AssertionError("aquarium duplicates GL");View water=(View)field(a,"aquarium");if(water.getHeight()<180*getTargetContext().getResources().getDisplayMetrics().density)throw new AssertionError("controls crowded out the water");shot("aquarium");select(8);click("Smooth rock, Place");select(0);click("Water plant, Place");select(1);click("Garden arch, Place");Object habitat=field(a,"habitat");int[]slots=(int[])field(habitat,"slots");if(slots[8]!=1||slots[0]!=0||slots[1]!=2)throw new AssertionError("native accessible placement");
  Object mesh=field(water,"sphere");if((Integer)field(mesh,"buffer")==0)throw new AssertionError("mesh was not uploaded to GPU");AtomicInteger error=new AtomicInteger(-1);CountDownLatch checked=new CountDownLatch(1);((android.opengl.GLSurfaceView)water).queueEvent(()->{error.set(android.opengl.GLES20.glGetError());checked.countDown();});if(!checked.await(15,TimeUnit.SECONDS)||error.get()!=0)throw new AssertionError("GL error "+error.get());shot("aquarium-decorated");
  getTargetContext().getSharedPreferences("family",0).edit().putString("theme","dark").putBoolean("reduce_motion",true).commit();ActivityMonitor monitor=addMonitor("com.littlemakers.village.nativeapp.AdventureActivity",null,false);ui(a::recreate);Activity fresh=waitForMonitorWithTimeout(monitor,20000);removeMonitor(monitor);if(fresh==null)throw new AssertionError("recreation");a=fresh;waitForIdleSync();waitFor(()->field(a,"aquarium")!=null&&(Long)field(field(a,"aquarium"),"renderedFrames")>0,"dark aquarium");if(((TextView)field(a,"objective")).getCurrentTextColor()!=Color.WHITE)throw new AssertionError("dark foreground");if((Integer)call(field(a,"habitat"),"count",new Class[0])!=3)throw new AssertionError("decorations lost");Object still=field(a,"aquarium");long frames=(Long)field(still,"renderedFrames");SystemClock.sleep(400);if((Long)field(still,"renderedFrames")>frames+1)throw new AssertionError("reduced mode renders while idle");shot("aquarium-dark");ui(a::finish);
  result.putString("stream","PASS "+captures+" captures: wardrobe purchase/equip idempotence, unchanged live avatar renderer, illustrated milestones, one GL viewport per scene, accessible sand-circle placement, GPU vertex buffer upload, GL_NO_ERROR, saved decor and white dark labels, reduced-motion idle. Software emulator is not a physical GPU/FPS benchmark.\n");finish(Activity.RESULT_OK,result);
 }catch(Throwable e){result.putString("stream","FAIL after "+captures+": "+android.util.Log.getStackTraceString(e));finish(Activity.RESULT_CANCELED,result);}}
}
